CREATE VIEW v225346 AS SELECT ST_ASTEXT(ST_CONVEXHULL(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(POINT(10 10),MULTIPOINT(0 0,10 10))'))), UNIX_TIMESTAMP(), UNIX_TIMESTAMP('2003-03-30 03:00:00'), SUM(x1.v224684 * (3 - x1.v224684)), SUM(DISTINCT SUBSTRING('x', 1, 3)) FROM v224683 AS x1 GROUP BY x1.v224684, x1.v224684, x1.v224684 WITH ROLLUP